<style>:root{--ink:#172033;--muted:#687386;--blue:#2563eb;--line:#e5eaf2;--canvas:#f7f9fc}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:15px Arial,sans-serif}.top{height:72px;padding:0 34px;display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid var(--line)}.brand{font-weight:800}.top span:last-child{color:var(--muted);font-size:13px}.main{max-width:1180px;margin:auto;padding:44px 30px}.eyebrow{color:var(--blue);font-size:11px;font-weight:700;letter-spacing:.13em;text-transform:uppercase}.heading{margin-bottom:28px}.heading h1{margin:8px 0;font-size:36px;letter-spacing:-.05em}.heading p,.sub{color:var(--muted)}.card{overflow:hidden;margin-bottom:24px;border:1px solid var(--line);border-radius:16px;background:#fff;box-shadow:0 10px 28px #1e315308}.card h2{margin:0;padding:22px 24px 0;font-size:19px}.sub{padding:0 24px;font-size:13px}.fields{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;padding:16px 24px}label{display:grid;gap:6px;color:var(--muted);font-size:12px;font-weight:700}input,select{min-height:38px;padding:8px 10px;border:1px solid var(--line);border-radius:8px;font:inherit}button{min-height:36px;padding:0 13px;border:0;border-radius:8px;color:#fff;background:var(--blue);font-weight:700;cursor:pointer}.button{margin:0 24px 22px}.success{margin-bottom:18px;padding:12px 14px;border-radius:9px;color:#17603a;background:#e8f8ef;font-size:13px}.error{margin:0 24px 18px;color:#b42318;font-size:13px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:720px}th,td{text-align:left;padding:14px 18px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-size:11px;text-transform:uppercase}td form{display:flex;gap:7px;align-items:center}.pill{display:inline-flex;padding:5px 9px;border-radius:99px;color:#2563eb;background:#eef4ff;font-size:12px;font-weight:700}.pill.closed,.pill.inactive{color:#687386;background:#f0f2f5}@media(max-width:700px){.top{padding:0 18px}.main{padding:30px 16px}.fields{grid-template-columns:1fr 1fr}}</style></head>
